<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>本地存储示例</title>
    <style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        input[type="text"] { margin-bottom: 10px; }
        button { margin-top: 10px; }
        ul { list-style-type: none; padding-left: 0; }
        li { margin-bottom: 5px; }
    </style>
</head>
<body>
    <h1>本地存储示例</h1>
    <input type="text" id="searchInput" placeholder="请输入搜索内容...">
    <button onclick="handleSearch()">搜索</button>
    <div id="resultDiv"></div>
    <script>
        // 示例数据
        const items = [
            {id: 1, name: "苹果", price: 5},
            {id: 2, name: "香蕉", price: 3},
            {id: 3, name: "橙子", price: 4},
            {id: 4, name: "西瓜", price: 2}
        ];

        // 存储数据
        function saveData() {
            localStorage.setItem('items', JSON.stringify(items));
        }

        // 加载数据
        function loadData() {
            const storedItems = JSON.parse(localStorage.getItem('items'));
            if (storedItems && storedItems.length > 0) {
                document.getElementById('resultDiv').innerHTML = '';
                items.forEach(item => {
                    const li = document.createElement('li');
                    li.textContent = item.name;
                    document.getElementById('resultDiv').appendChild(li);
                });
            } else {
                document.getElementById('resultDiv').textContent = '没有数据';
            }
        }

        // 处理搜索
        function handleSearch() {
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();
            const filtered = items.filter(item => item.name.toLowerCase().includes(searchTerm));
            const resultDiv = document.getElementById('resultDiv');
            resultDiv.innerHTML = '';
            filtered.forEach(item => {
                const li = document.createElement('li');
                li.textContent = item.name;
                resultDiv.appendChild(li);
            });
        }

        // 页面加载时加载数据
        window.onload = loadData;
    </script>
</body>
